        body: `■ ％は「全体を 100 と見たときの数」
割合 0.45 は「全体を 1 と見たときの 0.45」です。％はこれを「全体を 100 と見たとき」に言いかえたものなので、**100 倍**して 45% になります。100 倍することは小数点を右へ 2 けた動かすことと同じなので、「2けた動かす」という手順が出てきます。ひっかけの「0.4 → 4%」は 10 倍しかしていない、つまり全体を 10 と見た数（4割）で、**「割」なら 1 けた、「％」なら 2 けた**とちがうことが原因です。

■ 分数→小数→％の順にたどる理由
3/8 を％にするとき、分数のままでは 100 と見た数が見えません。まず 3÷8＝0.375 と小数にして「1 と見た数」にし、それを 100 倍して 37.5% にします。分数は「8 等分した 3 つぶん」、小数は「1 と見た大きさ」、％は「100 と見た大きさ」で、**表し方がちがうだけで同じ割合**です。

■ 得票率で「全体」が 100% になる理由
A 候補 540 票、B 候補 660 票、合計 1,200 票。
　A ＝ 540÷1,200 ＝ 0.45 → 45%
　B ＝ 660÷1,200 ＝ 0.55 → 55%
2人の票を合わせると全体の 1,200 票なので、割合を足すと 1（100%）になります。**部分の％をすべて足すと 100% になる**のは、部分が全体をちょうど分けているからです。ここが 100% にならなければ、どこかの計算がまちがっています。

■ 400×25 が 10,000 人になってしまう理由
「定員の 25%」は「定員を 100 と見たときの 25」なので、定員を 1 と見れば 0.25 です。％のまま 400×25 とかけると、**100 倍大きい数**（10,000 人）が出てしまいます。定員 400 人のホールに 10,000 人は入らないので、答えを出したら**現実にありえる数か**を必ず見ます。
　400×0.25 ＝ 100 人

★ ここがポイント：％は**全体を 100 と見た数**。小数→％は 100 倍（右へ 2 けた）、％→小数は 100 でわる（左へ 2 けた）。割は 1 けた、％は 2 けたで**動かすけた数がちがう**。部分の％を足すと 100% になる。`,
