        body: `■ 連比の数字は「同じ 1 あたり」の個数
A:B:C＝2:3:5 は、ある同じ量（1 あたり）を A が 2 個ぶん、B が 3 個ぶん、C が 5 個ぶん持つという意味です。合計 300 円は全部で 2＋3＋5＝10 個ぶんなので、1 あたり ＝ 300÷10＝30 円。A は 30×2＝60 円、B は 90 円、C は 150 円。**3 人になっても「合計 ÷ 比の和」の考え方は 2 人のときと同じ**です。

■ 1 つの量から 1 あたりを出す
A が 18 人で比の数字が 2 なら、1 あたり ＝ 18÷2＝9 人。C は 9×5＝45 人。ひっかけの 7.2 人は 18×2÷5 で、A の比の数字 2 でわるところを、C の 5 でわってしまったものです。**分かっている量は、その量に対応する比の数字でわる**。A の 18 人なら 2 でわります。人数が小数（7.2 人）になった時点でおかしいと気づけます。

■ 「4」がそのまま 40% ではない理由
A:B:C＝2:3:4 で C の割合を聞かれたら、全体は 2＋3＋4＝9 個ぶんで、C はそのうち 4 個ぶんなので 4÷9≒0.444 → **約 44.4%**。ひっかけの 40% は、比の 4 を「4 割」と読んだものです。％は**全体を 100 と見た数**なので、比の数字を％にするには、まず全体（比の和）でわらなければなりません。比の和が 10 のとき（2:3:5）だけは、たまたま 5 が 50% になりますが、それは 10 でわった結果です。

■ 2 人の比と 3 人の比のちがい
2 人の比なら「兄は弟の何倍」と 1 つの数でも表せますが、3 人以上になると「A は B の何倍、B は C の何倍」と 2 つ以上の数が必要になります。連比は**3 つの量を 1 つの「1 あたり」で同時に表す**ことで、この面倒を 1 行にまとめています。

★ ここがポイント：連比の数字は**同じ 1 あたりの個数**。合計は「比の和」個ぶんなので **合計 ÷ 比の和 ＝ 1 あたり**。1 つの量から求めるときは**その量に対応する比の数字でわる**。％にするには**比の和でわってから 100 倍**する。`,
