        body: `■ 35% と 60% は「同じ元の数」に対する割合
「ある数の 35% が 91」「同じ数の 60% は？」で、2 つの割合はどちらも**同じ元の数を 1 と見た割合**です。91 は 35% にあたる部分なので、91 に 0.6 をかけると「35% の 60%」という別の割合（0.35×0.6＝0.21、元の数の 21%）になってしまいます。ひっかけの 54.6 はこの 21% にあたる数です。60% を求めるには、**元の数（100%）に戻してから 0.6 をかけ**なければなりません。
　元の数 ＝ 91÷0.35 ＝ 260、60% ＝ 260×0.6 ＝ 156

■ 1% の量を通ると自然に元の数に戻る
91 が 35% なら、1% は 91÷35＝2.6。60% は 2.6×60＝156。100% は 2.6×100＝260。「35 でわって 60 をかける」という**1% を経由する道**は、元の数を経由するのと同じことで、なぜ元の数に戻すのかが分かりやすくなります。

■ 「4 割増しにしたら 182」で 0.4 でわってはいけない理由
「ある数を 4 割増しにしたら 182」は、元の数を 1 と見て**1.4 倍が 182** という意味です。182 は元の数の 40% ではなく 140% にあたります。ひっかけの 455 は 182÷0.4 で、「182 が 4 割ぶん」と読んだものです。455 を 4 割増しにすると 637 になり、182 とは大きくずれます。正しくは 182÷1.4＝130。**「増し」「引き」が付いたら（1±割合）でわる**という型を、相当算でも同じように使います。

■ 分数の割合でも型は同じ
「ある数の 3/8 が 45」なら 45÷(3/8)＝45×8/3＝120。3/8 は「8 等分した 3 つぶん」なので、45÷3＝15 が 1 つぶん、15×8＝120 が全体。小数でも分数でも**元の数 ＝ 部分 ÷ 割合**という 1 つの式です。

★ ここがポイント：別の割合を聞かれたら、**まず元の数（100%）に戻してから**その割合をかける。部分にそのまま割合をかけると「割合の割合」になる。「増し・引き」の付いた数は（1±割合）にあたるので、**その倍率でわって**元の数に戻す。`,
