        body: `■ 男子も女子も「同じ全体」を 1 と見た割合
男子が全体の 45% なら、女子は残りの 55% です。どちらも**クラス全体を 1（100%）と見た割合**なので、女子と男子の割合の差 55%−45%＝10% も「全体の 10%」という意味を持ちます。実際の人数の差は 6 人なので、全体の 10% が 6 人。だから全体は 6÷0.1＝60 人です。**同じものを 1 と見ている割合どうしなら、引き算した結果もその 1 に対する割合**になる——これが割合の差を使える理由です。

■ 6÷0.45 としてはいけない理由
ひっかけの 13.3 人は、6 人を男子の割合 0.45 でわったものです。でも 6 人は「男子の人数」ではなく「女子と男子の差」なので、対応する割合は 45% ではなく 10% です。**分かっている量（6 人）が、全体のどの割合にあたるか**を線分図で確かめてからわります。人数が小数（13.3 人）になった時点でおかしいと気づけます。

■ 「80% より 15 本多い」は 2 つの部分でできている
みかんはりんご 90 本の 80% より 15 本多い、なので みかん ＝ 90×0.8＋15 ＝ 72＋15 ＝ 87 本。ひっかけの 72 本は「80%」だけを計算して 15 本を足し忘れたものです。この問題は基準（りんご 90 本）が分かっているので割合をかけるだけですが、**「より△多い」の△を式に入れる**という点は、差のある相当算と同じです。

■ 線分図で「差」の区間を見つける
全体の線を 10 等分し、左から 4.5 目盛りまでが男子、残りが女子。男子の区間と女子の区間の**長さのちがいが 1 目盛り（10%）**で、そこに「6 人」と書きこめば、1 目盛り＝6 人、全体＝60 人 と図の上で読めます。2 つの割合が出てきたら、**同じ線の上に両方を描いて、差の区間がどれだけか**を見るのがこの型の線分図です。

★ ここがポイント：同じ全体を 1 と見た 2 つの割合は、**その差も全体に対する割合**。実際の量の差 ÷ 割合の差 ＝ 全体。分かっている量が「差」なのか「片方の量」なのかを線分図で確かめてから、対応する割合でわる。`,
