        heading: 'なぜ「1 あたりを①とおく」と解けるのか',
        figureId: 'sext02_s073_naze',
        body: `■ 比の数字は「1 あたり」の個数で、その 1 あたりが分からない
A:B＝3:2 は、ある同じ金額（1 あたり）を A が 3 個ぶん、B が 2 個ぶん持っているという意味です。この 1 あたりの金額が分かれば A も B も出せますが、問題文には書いてありません。そこで**1 あたりを ① とおき**、A＝③、B＝② と表します。

■ やりとりの後を「同じ ①」で書けるのが要点
A が 1,000 円わたすと A は ③−1,000、B は ②＋1,000 になります。**やりとりの前後で ① の大きさは変わらない**（1 あたりの金額は同じもの）ので、後の比 1:1 を「③−1,000 と ②＋1,000 が等しい」と 1 本の式にできます。
　③−1,000 ＝ ②＋1,000 → ① ＝ 2,000 → A ＝ 3×2,000 ＝ 6,000 円

■ 「1,000 円 ＝ 比の差 1 個ぶん」ではない理由
ひっかけの 3,000 円は、最初の比の差 3−2＝1 が 1,000 円だと考えたものです。でも 1,000 円は**やりとりで動いた金額**であって、最初の差ではありません。A が 1,000 円わたすと A は 1,000 円減り、B は 1,000 円増えるので、**差は 2,000 円縮まります**。最初の差 1 個ぶん（①）が 2,000 円縮まってちょうど 0（比 1:1）になったのだから、①＝2,000 円。1,000 円わたすと差が 2,000 円変わる、というところが見落としやすい点です。

■ B が受け取る分を式に入れ忘れると
ひっかけの (⑤−400):③＝1:1 は、A が 400 円減ることだけを書いて、B が 400 円増えることを書き忘れています。やりとりでは**わたした側が減り、受け取った側が同じだけ増える**ので、(⑤−400):(③＋400)＝1:1。⑤−400＝③＋400 → ②＝800 → ①＝400。B ＝ 3×400 ＝ 1,200 円。書き忘れると ①＝200 となり、B が 600 円という半分の答えになります。

★ ここがポイント：比の 1 あたりを **①とおき**、やりとりの後を同じ ① で書く。わたす人は減り、受け取る人は**同じだけ増える**ので両方を式に入れる。わたした金額は「最初の差」ではなく、**差を 2 倍ぶん縮める**。`,
