        body: `■ 利益率は原価に、割引率は定価にかかる
「3 割の利益を見込む」の 3 割は、**原価 600 円を 1 と見た 0.3**です。だから定価は 600×1.3＝780 円。「定価の 2 割引き」の 2 割は、**定価 780 円を 1 と見た 0.2**です。だから売価は 780×0.8＝624 円。かける相手（1 と見る量）が段階ごとにちがうので、順番を入れかえたり、どちらも原価にかけたりはできません。

■ 利益は「実際に売った値段」から出る
利益は売価 − 原価 ＝ 624−600 ＝ 24 円。ひっかけの 180 円は定価 − 原価で、**定価どおりに売れたときの利益**です。でも実際は 2 割引きで売ったので、手に入ったのは 624 円。お店に残るお金は「実際にもらった金額 − 仕入れに払った金額」なので、定価は利益の計算に直接は出てきません。**定価は「つけた値段」、売価は「もらった値段」**——この区別が損益算のすべてです。

■ 利益率の分母は原価
原価 900 円・定価 1,200 円のとき「原価に対する利益率」は (1,200−900)÷900 ＝ 300÷900 ＝ 0.333… → 約 33.3%。ひっかけの 25% は 300÷1,200 で、**定価を 1 と見た割合**です。「〇〇に対する」の〇〇が 1 と見る量なので、「原価に対する」なら分母は原価です。入試では「原価の何%」「原価に対して」と書かれていることがほとんどで、指示が無いときも原価に対する割合が標準です。

■ 3 割上げて 2 割引くと、利益は 1 割ではない
1.3×0.8＝1.04 なので、売価は原価の 1.04 倍、利益は原価の **4%**（24 円）です。「＋3 割 −2 割 ＝ ＋1 割」と足し引きすると 60 円になってしまいますが、2 割引きの基準が定価（原価より大きい）なので、引かれる金額は原価の 2 割（120 円）より大きい 156 円です。**増減はかけ算でつなぐ**（1.3×0.8）という、割合の増減の性質がそのまま使われています。

★ ここがポイント：利益率は**原価に**、割引率は**定価に**かける（原価×(1＋利益率)＝定価、定価×(1−割引率)＝売価）。利益は**売価 − 原価**で、定価は使わない。利益率の分母は原価。増減はかけ算でつなぐ（1.3×0.8＝1.04）。`,
